import json, glob, os, datetime as dt
cutoff = dt.datetime.now(dt.timezone.utc) - dt.timedelta(hours=48)
pending_q = []
for p in glob.glob("bus/inbox/*.jsonl"):
    agent = os.path.basename(p).replace(".jsonl","")
    questions, answers = [], set()
    for line in open(p, encoding="utf-8"):
        try: rec = json.loads(line)
        except Exception: continue
        try: ts_dt = dt.datetime.fromisoformat(rec.get("ts","").replace("Z","+00:00"))
        except Exception: continue
        if rec.get("event_type")=="question" and ts_dt>=cutoff: questions.append(rec.get("topic"))
        if rec.get("event_type")=="answer": answers.add(rec.get("topic"))
    for q in questions:
        if q not in answers: pending_q.append(f"{agent}/{q}")
print("pending_q =", pending_q)
